import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync, readdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { rotateLogs } from "./rotate.mjs";

function makeFakeIo(initialFiles) {
  const files = new Map(Object.entries(initialFiles));
  const calls = [];
  return {
    calls,
    exists(path) {
      calls.push(["exists", path]);
      return files.has(path);
    },
    size(path) {
      calls.push(["size", path]);
      return files.get(path);
    },
    rename(from, to) {
      calls.push(["rename", from, to]);
      const size = files.get(from);
      files.delete(from);
      files.set(to, size);
    },
    remove(path) {
      calls.push(["remove", path]);
      files.delete(path);
    },
  };
}

test("file under maxBytes is untouched", () => {
  const io = makeFakeIo({ "app.log": 99 });
  const actions = rotateLogs(["app.log"], 100, io);
  assert.deepEqual(actions, []);
});

test("boundary: file at exactly maxBytes rotates (< means >= rotates)", () => {
  const io = makeFakeIo({ "app.log": 100 });
  const actions = rotateLogs(["app.log"], 100, io);
  // size(100) < maxBytes(100) is false -> rotates
  assert.deepEqual(actions, [["rename", "app.log", "app.log.1"]]);
});

test("full cascade with existing .1/.2/.3", () => {
  const io = makeFakeIo({
    "app.log": 200,
    "app.log.1": 200,
    "app.log.2": 200,
    "app.log.3": 200,
  });
  const actions = rotateLogs(["app.log"], 100, io);
  assert.deepEqual(actions, [
    ["remove", "app.log.3"],
    ["rename", "app.log.2", "app.log.3"],
    ["rename", "app.log.1", "app.log.2"],
    ["rename", "app.log", "app.log.1"],
  ]);
});

test("missing base file is skipped", () => {
  const io = makeFakeIo({ "other.log": 500 });
  const actions = rotateLogs(["app.log"], 100, io);
  assert.deepEqual(actions, []);
});

test("two files are processed independently", () => {
  const io = makeFakeIo({ "a.log": 150, "b.log": 50 });
  const actions = rotateLogs(["a.log", "b.log"], 100, io);
  assert.deepEqual(actions, [["rename", "a.log", "a.log.1"]]);
});

test("hole in sequence: only .2 present, no .1", () => {
  const io = makeFakeIo({ "app.log": 200, "app.log.2": 200 });
  const actions = rotateLogs(["app.log"], 100, io);
  // .2 shifts to .3 (no .1 to shift), then base to .1
  assert.deepEqual(actions, [
    ["rename", "app.log.2", "app.log.3"],
    ["rename", "app.log", "app.log.1"],
  ]);
});

test("integration against real fs in a temp dir", () => {
  const dir = mkdtempSync(join(tmpdir(), "rotate-"));
  try {
    for (const name of ["app.log", "app.log.1", "app.log.2", "app.log.3"]) {
      writeFileSync(join(dir, name), "x".repeat(10));
    }
    const io = {
      exists: (p) => require("node:fs").existsSync(p),
      size: (p) => require("node:fs").statSync(p).size,
      rename: (f, t) => require("node:fs").renameSync(f, t),
      remove: (p) => require("node:fs").rmSync(p),
    };
    const base = join(dir, "app.log");
    const actions = rotateLogs([base], 5, io);

    assert.deepEqual(actions, [
      ["remove", `${base}.3`],
      ["rename", `${base}.2`, `${base}.3`],
      ["rename", `${base}.1`, `${base}.2`],
      ["rename", base, `${base}.1`],
    ]);
    assert.deepEqual(readdirSync(dir).sort(), [
      "app.log.1",
      "app.log.2",
      "app.log.3",
    ]);
    // rotated-out content preserved by the shift
    assert.equal(require("node:fs").readFileSync(`${base}.3`, "utf8"), "x".repeat(10));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

